INSERT INTO tipos_matricula (codigo, nombre, descripcion, activo, articulo_legal, creditos_minimos, requiere_pago, dias_habiles_limite, max_veces_desaprobado) VALUES
('MAT-001', 'Matrícula Regular (Art. 87.1)', 'Es la inscripción ordinaria que realizas dentro de las fechas, días y horas hábiles fijadas en el calendario académico oficial.', true, 'Art. 87.1', NULL, true, NULL, NULL),
('MAT-002', 'Matrícula Extemporánea o de Rezagados (Art. 87.2)', 'Se ejecuta fuera del plazo ordinario bajo fechas improrrogables y sujeta a penalidad financiera. Presencial: solo la primera semana de clases. Semipresencial y a distancia: hasta el primer viernes de la semana de inicio de clases.', true, 'Art. 87.2', NULL, true, 7, NULL),
('MAT-003', 'Matrícula de Estudiante Regular', 'Aplica cuando te inscribes en un mínimo de 12 créditos (o los que correspondan según tu ciclo) sin restricciones disciplinarias o académicas.', true, NULL, 12, true, NULL, NULL),
('MAT-004', 'Matrícula de Estudiante Irregular', 'Aplica cuando llevas menos de 12 créditos en el semestre, tienes cursos de arrastre de ciclos anteriores o estás nivelando asignaturas de distintos ciclos.', true, NULL, NULL, true, NULL, NULL),
('MAT-005', 'Matrícula en Asignaturas Extraprogramáticas (Art. 86.3.1 y 122)', 'Permite llevar cursos no ofertados regularmente para regularizar tu avance curricular. No requiere matrícula regular ni pago adicional, pero exige un mínimo de inscritos para abrirse.', true, 'Art. 86.3.1 y 122', NULL, false, NULL, NULL),
('MAT-006', 'Matrícula en Asignaturas Dirigidas (Art. 86.3.2)', 'Modalidad excepcional para llevar un curso de forma personalizada con un docente. Procede solo si culminas la carrera en el año en curso y no tienes pendiente ningún requisito de egreso.', true, 'Art. 86.3.2', NULL, true, NULL, NULL),
('MAT-007', 'Matrícula Condicionada por Rendimiento Académico', 'Se activa por mandato de la Ley Universitaria al desaprobar una misma asignatura tres veces. Implica separación temporal de un año; al reincorporarte, solo puedes matricularte en esa asignatura.', true, NULL, NULL, true, NULL, 3),
('MAT-008', 'Matrícula de Ingresantes', 'Proceso exclusivo para alumnos nuevos (cachimbos) admitidos por examen ordinario, CEPRE, primeros puestos, traslado externo u otras modalidades de admisión.', true, NULL, NULL, true, NULL, NULL),
('MAT-009', 'Matrícula por Reingreso o Reactualización', 'Dirigida a estudiantes que dejaron de estudiar (con o sin reserva de matrícula previa) y tramitan su retorno, adecuándose al plan de estudios vigente.', true, NULL, NULL, true, NULL, NULL),
('MAT-010', 'Matrícula de Ciclo de Verano o Nivelación', 'Habilitada en el periodo vacacional (enero-febrero) para adelantar cursos, nivelar asignaturas desaprobadas o llevar cursos de reforzamiento para ingresantes.', true, NULL, NULL, true, NULL, NULL);
